#!/usr/bin/env python3
from __future__ import annotations

import base64
import selectors
import subprocess
import sys
import time
from pathlib import Path
from typing import TextIO, cast

PAYLOAD_B64 = """"""
CANDIDATE = 'compiled_branchless_reduce_overhead_markstep'
TIMEOUT_S = 2700

payload = Path('/content/f5tts_fullgraph_speedup_bench.py')
payload.write_bytes(base64.b64decode(PAYLOAD_B64.encode('ascii')))
print(f'LAUNCHER_WROTE_PAYLOAD={payload} bytes={payload.stat().st_size} candidate={CANDIDATE}', flush=True)
cmd = [
    sys.executable,
    str(payload),
    '--work-dir',
    f'/content/f5tts_{CANDIDATE}_l4_v2',
    '--samples', '1000',
    '--fetch-rows', '5000',
    '--epochs', '1',
    '--candidates', CANDIDATE,
]
print('RUNNER_CMD=' + ' '.join(cmd), flush=True)
proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
assert proc.stdout is not None
selector = selectors.DefaultSelector()
selector.register(proc.stdout, selectors.EVENT_READ)
started = time.monotonic()
timed_out = False
while True:
    events = selector.select(timeout=30)
    if events:
        for key, _ in events:
            stream = cast(TextIO, key.fileobj)
            line = stream.readline()
            if line:
                print(line, end='', flush=True)
    else:
        elapsed = time.monotonic() - started
        print(f'RUNNER_HEARTBEAT elapsed_s={elapsed:.1f} returncode={proc.poll()}', flush=True)
        if elapsed > TIMEOUT_S and proc.poll() is None:
            timed_out = True
            print(f'RUNNER_TIMEOUT_KILL elapsed_s={elapsed:.1f} timeout_s={TIMEOUT_S}', flush=True)
            proc.kill()
    if proc.poll() is not None:
        for line in proc.stdout:
            print(line, end='', flush=True)
        break
print(f'RUNNER_RETURN_CODE={proc.returncode} timed_out={timed_out}', flush=True)
if timed_out and proc.returncode == -9:
    raise SystemExit(124)
raise SystemExit(proc.returncode)
